// Все настройки прототипа. Меняй числа, сохраняй файл и обновляй страницу (F5).
// Единицы: метры и секунды. Метры условные, это масштаб мира, а не реальные размеры.
// ВРЕМЕННО: все числа ниже стартовые, подобраны для первой проверки.

const CONFIG = {

  // ---------- Падение и наклон ----------

  // Сила падения вниз, м/с².
  // Больше: шар быстрее разгоняется и на обход остаётся меньше времени.
  fallGravity: 2,

  // Сила смещения вбок при полном наклоне, м/с².
  // Больше: шар резче уходит в сторону.
  sideGravity: 8,

  // Скорость отклика клавиатуры: сколько полных наклонов в секунду, 1/с.
  // Больше: наклон с клавиш включается и отпускается резче.
  // Меньше: движение плавнее, но реакция запаздывает.
  keyboardTiltRate: 6,


  // ---------- Датчик телефона ----------

  // Угол поворота телефона, при котором наклон считается полным, градусы.
  // Меньше: шар отзывчивее, хватает маленького движения кистью.
  // Больше: управление точнее, но поворачивать телефон надо сильнее.
  sensorFullTiltAngle: 35,

  // Мёртвая зона: повороты меньше этого угла игнорируются, градусы.
  // Больше: дрожание рук не двигает шар, но отклик на малый наклон пропадает.
  // 0: мёртвой зоны нет.
  sensorDeadZoneAngle: 3,

  // Как быстро шар реагирует на поворот телефона: полных наклонов в секунду, 1/с.
  // Больше: реакция быстрее, но заметнее дрожание рук.
  // Меньше: движение плавнее, но с запаздыванием.
  sensorTiltRate: 8,

  // Если шар уходит не в ту сторону, поставь true.
  sensorInvert: false,


  // ---------- Защита физики ----------

  // Защитный потолок скорости, м/с. Это не игровой параметр.
  // Нужен, чтобы физика не ломалась. Выше 100 ставить не стоит:
  // движок ограничивает путь за один шаг.
  safetyMaxSpeed: 60,


  // ---------- Шар ----------

  // Радиус шара, м.
  // Больше: шар заметнее, но обойти препятствия труднее.
  ballRadius: 0.18,

  // Плотность шара, кг/м². На падение почти не влияет, важна для столкновений.
  ballDensity: 1,

  // Упругость шара, от 0 до 1.
  // 0: удар без отскока. 1: отскок почти без потери скорости.
  ballRestitution: 0.3,

  // Трение шара о предметы, от 0 до 1.
  // Больше: при касании стенки шар сильнее закручивается и теряет больше скорости.
  ballFriction: 0.3,


  // ---------- Труба ----------

  // Ширина трубы внутри, м.
  // Меньше: сложнее, это главный рычаг сложности.
  pipeWidth: 3,

  // Длина трубы от верха до низа, м.
  // Больше: дольше падение и выше скорость в конце.
  pipeLength: 40,

  // Ветки. side: "left" или "right" — из какой стенки торчит.
  // depth: глубина от верха трубы, м. length: насколько торчит внутрь, м.
  // thickness: толщина, м. Можно добавлять и удалять строки.
  branches: [
    { side: "left",  depth: 10, length: 0.9, thickness: 0.12 },
    { side: "right", depth: 20, length: 0.9, thickness: 0.12 },
  ],


  // ---------- Камера и вид ----------

  // Сколько метров мира видно по ширине экрана.
  // Больше: камера дальше, всё мельче, но труба видна с запасом по бокам.
  viewWidth: 3.6,

  // Где держать шар по высоте экрана: 0 — верх, 1 — низ.
  // Меньше: шар выше и препятствия видны раньше.
  cameraBallPosition: 0.3,

  // Шаг поперечных меток на стенках, м. Без них в прямой трубе не видно движения.
  // Меньше: ощущение скорости сильнее.
  tickSpacing: 1,
};
